def _ratings(profile: str, overrides: dict | None = None) -> dict:
    values = dict(zip([c[0] for c in CRITERIA], PROFILES[profile]))
    values.update(overrides or {})
    return values


def _service(sid, name, permit_type, examples, profile, grade, decision, target, problem, advantages, disadvantages, risks, conditions, rationale, source, readiness="Perlu validasi scope"):
    return {
        "id": sid, "name": name, "permit_type": permit_type, "examples": examples,
        "grade": grade, "decision": decision, "target": target, "problem": problem,
        "advantages": advantages, "disadvantages": disadvantages, "risks": risks,
        "conditions": conditions, "rationale": rationale, "source": source,
        "readiness": readiness, "ratings": _ratings(profile),
    }


